tools.input:
W=<trial>; mkdir -p $W/work && cd $W/work && cat > q.tuft <<'EOF'
@h := find text ".expect(" in "crates/" at "e56621f7acf0d3392add5d814c35134b66c872a7" limit 100;
@e := retain @h around lines 0;
@v := project @e [path, line, excerpt(max_chars: 300)];
emit @v budget_tokens 4000;
EOF
<writfold> tuft run q.tuft --repo $W/repo --state $W/state --out $W/work/rows.txt; echo "exit=$?"; cat $W/work/rows.txt
